<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ArrowLeft, ArrowDown, ArrowUp, ChevronDown, Pencil, Plus, Trash2 } from 'lucide-vue-next'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue';import WorkspaceTabs from '../components/WorkspaceTabs.vue';import StatusBadge from '../components/StatusBadge.vue';import JalaliDatePicker from '../components/JalaliDatePicker.vue';import OrderItemConfigurator from '../components/OrderItemConfigurator.vue';import DocumentMetadataPanel from '../components/DocumentMetadataPanel.vue';import type { QuoteRecord, QuotePayload } from '../api/quotes';import { quotesApi } from '../api/quotes';import type { OrderItemPayload } from '../api/orders';import type { CurrencyUnit } from '../utils/currency';import { formatMoney,formatMoneyInput,parseMoneyInput } from '../utils/currency';import { formatDateTime } from '../utils/date'
const props=defineProps<{quote:QuoteRecord;currencyUnit:CurrencyUnit;customers:any[];services:any[];materials:any[]}>();const emit=defineEmits<{back:[];notify:[message:string];saved:[quote:QuoteRecord];converted:[orderId:string]}>();const tab=ref('Overview');const customerId=ref('');const expiryDate=ref<string|null>(null);const notes=ref('');const discountText=ref('');const editorOpen=ref(false);const editingItem=ref<any|null>(null);const saving=ref(false);const tabs=['Overview','Items','Files'];const customer=computed(()=>props.customers.find(c=>c.id===customerId.value));
watch(()=>props.quote,(q)=>{customerId.value=q.customerId||'';expiryDate.value=q.expiryDate;notes.value=q.notes;discountText.value=formatMoneyInput(q.discountRial,props.currencyUnit)},{immediate:true});function tone(v:string){return v==='Accepted'||v==='Converted'?'green':v==='Sent'?'blue':v==='Rejected'?'red':v==='Expired'?'amber':'slate'}function money(v:number){return formatMoney(v,props.currencyUnit)}function payload():QuotePayload{return{customerId:customerId.value,expiryDate:expiryDate.value,notes:notes.value,discountRial:parseMoneyInput(discountText.value,props.currencyUnit)||0}}
async function saveMetadata(){saving.value=true;try{emit('saved',await quotesApi.update(props.quote.id,payload()));emit('notify','Quote details saved')}catch(e){emit('notify',String(e))}finally{saving.value=false}}async function configured(input:OrderItemPayload){saving.value=true;try{const result=editingItem.value?await quotesApi.replaceItem(props.quote.id,editingItem.value.id,input):await quotesApi.addItem(props.quote.id,input);emit('saved',result);editorOpen.value=false;editingItem.value=null;emit('notify',editingItem.value?'Item replaced':'Item added')}catch(e){emit('notify',String(e))}finally{saving.value=false}}async function remove(item:any){try{emit('saved',await quotesApi.removeItem(props.quote.id,item.id));emit('notify','Item removed')}catch(e){emit('notify',String(e))}}async function move(item:any,delta:number){const items=[...props.quote.items].sort((a,b)=>a.position-b.position);const i=items.findIndex(x=>x.id===item.id);const n=i+delta;if(n<0||n>=items.length)return;[items[i],items[n]]=[items[n],items[i]];try{emit('saved',await quotesApi.reorderItems(props.quote.id,items.map(x=>x.id)))}catch(e){emit('notify',String(e))}}async function changeStatus(e:Event){try{emit('saved',await quotesApi.status(props.quote.id,(e.target as HTMLSelectElement).value));emit('notify','Quote status updated')}catch(err){emit('notify',String(err))}}async function discount(){try{const amount=parseMoneyInput(discountText.value,props.currencyUnit);if(amount===null)throw new Error('Enter a valid discount');emit('saved',await quotesApi.discount(props.quote.id,amount));emit('notify','Discount applied')}catch(e){emit('notify',String(e))}}async function convert(){if(props.quote.convertedOrderId)return;try{const result=await quotesApi.convert(props.quote.id);emit('saved',result);emit('converted',result.convertedOrderId);emit('notify','Quote converted to order')}catch(e){emit('notify',String(e))}}
</script>
<template><div class="order-workspace"><WorkspaceStickyStack :flush="true"><header class="order-workspace-header"><button class="back-button" @click="emit('back')"><ArrowLeft :size="16"/>Quotes</button><div class="order-heading-copy"><p class="eyebrow">Sales / Quote workspace</p><div class="order-title-row"><h1>{{ quote.quoteNumber }}</h1><StatusBadge :label="quote.status" :tone="tone(quote.status)"/></div><p class="heading-description">{{ quote.customerName||'Walk-in customer' }} · {{ quote.items.length }} line items</p></div><div class="order-header-actions"><span class="select-control"><select :value="quote.status" aria-label="Quote status" @change="changeStatus"><option>Draft</option><option>Sent</option><option>Accepted</option><option>Rejected</option><option>Expired</option><option>Converted</option></select><ChevronDown class="select-chevron" :size="14"/></span><button v-if="quote.status==='Accepted'&&!quote.convertedOrderId" class="button button-primary" :disabled="saving" @click="convert">Convert to order</button><button class="button button-secondary" :disabled="saving||quote.status!=='Draft'" @click="saveMetadata">Save quote</button></div></header><section class="order-meta-strip"><div class="order-meta-cell"><span class="meta-label">Customer</span><span class="meta-value">{{ customer?.name||quote.customerName||'Walk-in customer' }}</span><span class="meta-detail">{{ customer?.phone||quote.customerPhone||'No contact details' }}</span></div><div class="order-meta-cell"><span class="meta-label">Created</span><span class="meta-value">{{ formatDateTime(quote.createdAt) }}</span><span class="meta-detail">Jalali presentation</span></div><div class="order-meta-cell"><span class="meta-label">Expiry date</span><JalaliDatePicker v-model="expiryDate" placeholder="Set expiry date"/></div><div class="order-meta-cell"><span class="meta-label">Snapshot rule</span><span class="meta-value">Saved pricing</span><span class="meta-detail">Reconfigure explicitly</span></div></section><WorkspaceTabs :tabs="tabs" :active-tab="tab" @update:active-tab="tab=$event"/></WorkspaceStickyStack><section v-if="tab==='Overview'" class="order-content-grid"><section class="panel order-details-panel"><header class="panel-header"><div><h2 class="panel-title">Quote details</h2><p class="panel-subtitle">Customer and commercial context</p></div></header><div class="order-form"><label>Customer<span class="select-control"><select v-model="customerId"><option value="">Walk-in customer</option><option v-for="c in customers.filter((x:any)=>x.active||x.id===customerId)" :key="c.id" :value="c.id">{{ c.name }}</option></select><ChevronDown class="select-chevron" :size="14"/></span></label><label>Notes<textarea v-model="notes" rows="5" placeholder="Quote notes"/></label></div><button class="button button-primary" :disabled="saving||quote.status!=='Draft'" @click="saveMetadata">Save details</button></section><section class="panel order-summary-panel"><header class="panel-header"><h2 class="panel-title">Quote summary</h2></header><div class="summary-metrics"><span>Subtotal<strong>{{ money(quote.subtotalRial) }}</strong></span><span>Discount<strong>{{ money(quote.discountRial) }}</strong></span><span>Total<strong>{{ money(quote.totalRial) }}</strong></span><span>Estimated cost<strong>{{ money(quote.estimatedCostRial) }}</strong></span></div><label class="discount-field">Quote discount<input :value="discountText" @input="discountText=($event.target as HTMLInputElement).value" @blur="discountText=formatMoneyInput(parseMoneyInput(discountText,props.currencyUnit)||0,props.currencyUnit)"/><button class="button button-secondary" :disabled="quote.status!=='Draft'" @click="discount">Apply</button></label><div v-if="quote.convertedOrderId" class="panel-callout">Linked order: {{ quote.convertedOrderId }}</div></section></section><section v-else-if="tab==='Items'" class="order-items-area"><div v-if="!editorOpen" class="panel"><header class="panel-header"><div><h2 class="panel-title">Configured items</h2><p class="panel-subtitle">Each item keeps its accepted service and pricing snapshot.</p></div><button class="button button-primary" :disabled="quote.status!=='Draft'" @click="editorOpen=true"><Plus :size="15"/>Add service item</button></header><div v-if="!quote.items.length" class="workspace-state">No items yet. Add the first configured service.</div><div v-for="item in [...quote.items].sort((a,b)=>a.position-b.position)" :key="item.id" class="order-item-row"><div class="item-position">{{ item.position+1 }}</div><div class="item-copy"><strong>{{ item.serviceName }}</strong><span>{{ item.quantity }} {{ item.quantityUnit }}<template v-if="item.notes"> · {{ item.notes }}</template></span><small>Accepted snapshot · {{ item.resolvedParametersJson?JSON.parse(item.resolvedParametersJson).length:0 }} parameters</small></div><div class="item-prices"><span>Cost {{ money(item.estimatedCostRial) }}</span><strong>{{ money(item.sellingPriceRial) }}</strong></div><div class="item-actions"><button class="icon-button" @click="move(item,-1)"><ArrowUp :size="14"/></button><button class="icon-button" @click="move(item,1)"><ArrowDown :size="14"/></button><button class="icon-button" :disabled="quote.status!=='Draft'" @click="editingItem=item;editorOpen=true"><Pencil :size="14"/></button><button class="icon-button danger" :disabled="quote.status!=='Draft'" @click="remove(item)"><Trash2 :size="14"/></button></div></div></div><OrderItemConfigurator v-else :services="services" :materials="materials" :currency-unit="currencyUnit" document-label="quote" :initial="editingItem" @configured="configured" @cancel="editorOpen=false;editingItem=null"/></section><DocumentMetadataPanel v-else owner-type="quote" :owner-id="quote.id" :protected-context="quote.status !== 'Draft'" @notify="emit('notify',$event)"/></div></template>
